public interface ILetter { void Draw(); ILetter Clone(); }

public sealed class Envelope : ILetter      // value-like facade
{
    private readonly ILetter _letter;
    public Envelope(ILetter letter) => _letter = letter;
    public void Draw() => _letter.Draw();           // forwarding
    public ILetter Clone() => new Envelope(_letter.Clone());  // deep copy
}
